583	static nlohmann::json merge(const nlohmann::json &a, const nlohmann::json &b)
584	{
585	    nlohmann::json result = a.flatten();
586	    nlohmann::json tmp = b.flatten();
587	
588	    for (nlohmann::json::iterator it = tmp.begin(); it != tmp.end(); ++it)
589	    {
590	        result[it.key()] = it.value();
591	    }
592	
593	    return result.unflatten();
594	}
