607	bool Preferences::set(QString name, QVariant value)
608	{
609	    QPointerVariant *ptr = nullptr;
610	    for(auto s : descr) {
611	        if(s.name == name) {
612	            ptr = &s.var;
613	            break;
614	        }
615	    }
616	    if(!ptr) {
617	        // check the driver settings
618	        for(auto driver : DeviceDriver::getDrivers()) {
619	            for(auto s : driver->driverSpecificSettings()) {
620	                if(s.name == name) {
621	                    ptr = &s.var;
622	                    break;
623	                }
624	            }
625	            if(ptr) {
626	                break;
627	            }
628	        }
629	    }
630	    if(ptr) {
631	        try {
632	            ptr->setValue(value);
633	            return true;
634	        } catch (const std::runtime_error&) {
635	            // failed to set variable, likely wrong format for the QVariant
636	            return false;
637	        }
638	    } else {
639	        // not found
640	        return false;
641	    }
642	}
