644	QVariant Preferences::get(QString name)
645	{
646	    for(auto &s : descr) {
647	        if(s.name == name) {
648	            return s.var.value();
649	        }
650	    }
651	    for(auto driver : DeviceDriver::getDrivers()) {
652	        for(auto &s : driver->driverSpecificSettings()) {
653	            if(s.name == name) {
654	                return s.var.value();
655	            }
656	        }
657	    }
658	    // not found
659	    return QVariant();
660	}
